iv id="horarios"><p class="muted">Selecione profissional e data.</p></div><button class="btn btn-full" id="btnAgendar" disabled>Confirmar agendamento</button></form></div></main><script>window.AURA_AGENDAMENTO=true;</script><script src="js/app.js"></script></body></html><?php unset($_SESSION['form_old']);?>
